#include <iostream>

// Recursive factorial: incurs O(n) stack frames
long long factorialRecursive(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorialRecursive(n - 1); // Pending multiplication
}

// Iterative factorial: O(1) auxiliary space, no stack growth
long long factorialIterative(int n) {
    long long result = 1;
    for (int i = 2; i <= n; ++i) {
        result *= i;
    }
    return result;
}

int main() {
    int n = 5;
    std::cout << "Recursive factorial of " << n << ": " << factorialRecursive(n) << "\n";
    std::cout << "Iterative factorial of " << n << ": " << factorialIterative(n) << "\n";
    return 0;
}

#include <iostream>

// Auxiliary tail-recursive helper for factorial
long long factorialTail(int n, long long result) {
    if (n <= 1) {
        return result; // Base case: return accumulated value
    }
    // No pending operation on return: Tail call
    return factorialTail(n - 1, n * result);
}

// Public wrapper function
long long factorial(int n) {
    return factorialTail(n, 1);
}

// Check Point 17.17: Tail-recursive Fibonacci
long long fibTail(int n, long long a, long long b) {
    if (n == 0) return a;
    if (n == 1) return b;
    return fibTail(n - 1, b, a + b);
}

long long fib(int n) {
    return fibTail(n, 0, 1);
}

int main() {
    std::cout << "Tail-recursive 6!: " << factorial(6) << "\n";
    std::cout << "Tail-recursive fib(10): " << fib(10) << "\n";
    return 0;
}
